import com.hopeless.infinity.planet.*; import java.awt.image.BufferedImage; import java.awt.*; import java.util.*;
/** BiomeMap seed out.png: the home planet's biomes on a world map (longitude x latitude), from Terrain.biome as the generator uses it. Saved tool. */
public class BiomeMap { static final Map<String, Integer> C = new HashMap<>(); static { String[] kv = {"desert","dcc890","badlands","c0603a","savanna","b0b050","plains","8ec060","forest","3a7a30","birch_forest","6a9a50","dark_forest","2a5020","flower_forest","b070a0","swamp","4a6040","jungle","1a8a20","sparse_jungle","4aa040","taiga","3a6a50","old_growth_spruce_taiga","2a5040","snowy_taiga","90b0a0","snowy_plains","e8f0f0","ice_spikes","b0d8f0","meadow","90c080","windswept_hills","8a9a80","snowy_slopes","f0f0f8","stony_peaks","909090","jagged_peaks","c8c8d0","frozen_peaks","d0e0f0","beach","e8d8a0","snowy_beach","e0e0d0","stony_shore","808080","hopelessinfinity:volcanic","4c4c50","mangrove_swamp","5a6a30","cherry_grove","e8a0c0","bamboo_jungle","6ab830"};
    for (int i = 0; i < kv.length; i += 2) C.put(kv[i], Integer.parseInt(kv[i + 1], 16)); }
  public static void main(String[] a) throws Exception { PlanetWorld w = new PlanetWorld(Long.parseLong(a[0])); int W = 1200, H = 600; BufferedImage img = new BufferedImage(W, H + 26, BufferedImage.TYPE_INT_RGB);
    for (int j = 0; j < H; j++) for (int i = 0; i < W; i++) { double lat = Math.PI / 2 - Math.PI * (j + 0.5) / H, lon = 2 * Math.PI * (i + 0.5) / W - Math.PI; double[] s = {Math.cos(lat) * Math.cos(lon), Math.cos(lat) * Math.sin(lon), Math.sin(lat)}; double h = w.terrain.heightM(s, w.cube.R);
      int rgb; if (h <= 0) { double k = Math.min(1, -h / 5000); rgb = new Color((int) (40 - 25 * k), (int) (90 - 55 * k), (int) (170 - 70 * k)).getRGB(); } else rgb = C.getOrDefault(w.terrain.biome(s, h).key, 0xff00ff); img.setRGB(i, 26 + j, rgb); }
    Graphics2D g = img.createGraphics(); g.setColor(new Color(0x10141c)); g.fillRect(0, 0, W, 26); g.setColor(Color.WHITE); g.setFont(new Font("SansSerif", Font.PLAIN, 13));
    g.drawString("Hopeless Infinity seed " + a[0] + " home planet biomes (Terrain.biome; z = spin pole up), equirectangular", 6, 18); javax.imageio.ImageIO.write(img, "png", new java.io.File(a[1])); } }
